func DecodeFrames(data []byte) ([]Frame, error)
```

The byte stream contains zero or more consecutive frames. Each frame is encoded as:

1. one flags byte;
2. one payload-length byte `N`;
3. exactly `N` payload bytes;
4. one checksum byte.

The checksum is the bitwise XOR of the flags byte, the payload-length byte, and every payload byte. Decode all valid frames in order. An empty stream is valid and returns an empty, non-nil slice with a nil error.

A frame is malformed if the stream ends before all four logical parts are available or if its checksum is incorrect. On any malformed frame, return `nil` and a non-nil error; do not return a partial result. Payload slices may refer to the supplied `data` buffer.

Use only the Go standard library. Do not access the filesystem, network, clock, or randomness.","reference_code":"package solution

import "errors"

type Frame struct {
	Flags   byte
	Payload []byte
}

func DecodeFrames(data []byte) ([]Frame, error) {
	frames := make([]Frame, 0)
	for offset := 0; offset < len(data); {
		if len(data)-offset < 3 {
			return nil, errors.New("truncated frame")
		}

		flags := data[offset]
		payloadLength := int(data[offset+1])
		frameLength := payloadLength + 3
		if len(data)-offset < frameLength {
			return nil, errors.New("truncated frame")
		}

		payloadStart := offset + 2
		payloadEnd := payloadStart + payloadLength
		checksum := flags ^ byte(payloadLength)
		for _, value := range data[payloadStart:payloadEnd] {
			checksum ^= value
		}
		if data[payloadEnd] != checksum {
			return nil, errors.New("invalid checksum")
		}

		frames = append(frames, Frame{
			Flags:   flags,
			Payload: data[payloadStart:payloadEnd],
		})
		offset += frameLength
	}
	return frames, nil
}
