{"items":[{"id":"cap-v2-associative_aggregation-go-generation-01","test_code":"package solution

import (
	"reflect"
	"testing"
)

func TestCountActivationsAggregatesByTenantAndFeature(t *testing.T) {
	input := []Activation{
		{Tenant: "tenant-a", Feature: "search"},
		{Tenant: "tenant-b", Feature: "search"},
		{Tenant: "tenant-a", Feature: "search"},
		{Tenant: "tenant-a", Feature: "checkout"},
		{Tenant: "tenant-b", Feature: "search"},
		{Tenant: "tenant-b", Feature: "recommendations"},
	}
	want := map[string]map[string]int{
		"tenant-a": {"search": 2, "checkout": 1},
		"tenant-b": {"search": 2, "recommendations": 1},
	}

	if got := CountActivations(input); !reflect.DeepEqual(got, want) {
		t.Fatalf("CountActivations() = %#v, want %#v", got, want)
	}
}

func TestCountActivationsTreatsEmptyStringsAsOrdinaryKeys(t *testing.T) {
	input := []Activation{
		{Tenant: "", Feature: ""},
		{Tenant: "", Feature: "flag"},
		{Tenant: "", Feature: ""},
		{Tenant: "tenant", Feature: ""},
	}
	want := map[string]map[string]int{
		"":       {"": 2, "flag": 1},
		"tenant": {"": 1},
	}

	if got := CountActivations(input); !reflect.DeepEqual(got, want) {
		t.Fatalf("CountActivations() = %#v, want %#v", got, want)
	}
}

func TestCountActivationsEmptyInputsReturnNonNilEmptyMap(t *testing.T) {
	for _, input := range [][]Activation{nil, {}} {
		got := CountActivations(input)
		if got == nil {
			t.Fatal("CountActivations() returned a nil map for empty input")
		}
		if len(got) != 0 {
			t.Fatalf("CountActivations() returned %#v for empty input", got)
		}
	}
}

func TestCountActivationsDoesNotModifyInputAndIsStable(t *testing.T) {
	input := []Activation{
		{Tenant: "x", Feature: "a"},
		{Tenant: "x", Feature: "a"},
		{Tenant: "y", Feature: "b"},
	}
	before := append([]Activation(nil), input...)

	first := CountActivations(input)
	second := CountActivations(input)

	if !reflect.DeepEqual(input, before) {
		t.Fatalf("input changed: got %#v, want %#v", input, before)
	}
	if !reflect.DeepEqual(first, second) {
		t.Fatalf("repeated calls differ: first %#v, second %#v", first, second)
	}
}
