func TestMergeCountMapsSumsEveryKey(t *testing.T) {
	groups := []map[string]int{
		{"a": 2, "shared": 5},
		{"b": 3, "shared": -2},
		nil,
		{"a": -1, "shared": 4},
	}
	want := map[string]int{"a": 1, "b": 3, "shared": 7}

	if got := MergeCountMaps(groups); !reflect.DeepEqual(got, want) {
		t.Fatalf("MergeCountMaps() = %#v, want %#v", got, want)
	}
}

func TestMergeCountMapsEmptyInputReturnsNonNilMap(t *testing.T) {
	for _, groups := range [][]map[string]int{nil, {}} {
		got := MergeCountMaps(groups)
		if got == nil {
			t.Fatal("MergeCountMaps() returned a nil map for empty input")
		}
		if len(got) != 0 {
			t.Fatalf("MergeCountMaps() returned %#v for empty input", got)
		}
	}
}

func TestMergeCountMapsDoesNotMutateInputs(t *testing.T) {
	first := map[string]int{"x": 1, "common": 2}
	second := map[string]int{"y": 3, "common": 4}
	groups := []map[string]int{first, second}
	firstBefore := map[string]int{"x": 1, "common": 2}
	secondBefore := map[string]int{"y": 3, "common": 4}

	_ = MergeCountMaps(groups)

	if !reflect.DeepEqual(first, firstBefore) {
		t.Fatalf("first input was modified: got %#v, want %#v", first, firstBefore)
	}
	if !reflect.DeepEqual(second, secondBefore) {
		t.Fatalf("second input was modified: got %#v, want %#v", second, secondBefore)
	}
}

func TestMergeCountMapsResultDoesNotAliasAnyInput(t *testing.T) {
	first := map[string]int{"first": 1, "shared": 2}
	second := map[string]int{"second": 3, "shared": 4}
	got := MergeCountMaps([]map[string]int{first, second})

	got["first"] = 100
	got["second"] = 200
	got["new"] = 300

	if !reflect.DeepEqual(first, map[string]int{"first": 1, "shared": 2}) {
		t.Fatalf("mutating result changed first input: %#v", first)
	}
	if !reflect.DeepEqual(second, map[string]int{"second": 3, "shared": 4}) {
		t.Fatalf("mutating result changed second input: %#v", second)
	}

	first["first"] = -1
	second["second"] = -2
	if got["first"] != 100 || got["second"] != 200 {
		t.Fatalf("mutating inputs changed result: %#v", got)
	}
}

func TestMergeCountMapsSingleInputIsStillCopied(t *testing.T) {
	input := map[string]int{"only": 8}
	got := MergeCountMaps([]map[string]int{input})
	got["only"] = 9

	if input["only"] != 8 {
		t.Fatalf("single input aliases result: input is %#v", input)
	}
}
