"},{"id":"cap-v2-binary_and_bitwise-go-generation-01","test_code":"package solution

import (
	"bytes"
	"reflect"
	"testing"
)

func encodedFrame(flags byte, payload []byte) []byte {
	length := byte(len(payload))
	checksum := flags ^ length
	frame := []byte{flags, length}
	for _, b := range payload {
		frame = append(frame, b)
		checksum ^= b
	}
	return append(frame, checksum)
}

func TestDecodeFramesDecodesConsecutiveFrames(t *testing.T) {
	data := append(encodedFrame(0x81, []byte{0x10, 0x20, 0x30}), encodedFrame(0x02, []byte{0xff})...)
	want := []Frame{
		{Flags: 0x81, Payload: []byte{0x10, 0x20, 0x30}},
		{Flags: 0x02, Payload: []byte{0xff}},
	}

	got, err := DecodeFrames(data)
	if err != nil {
		t.Fatalf("DecodeFrames() returned unexpected error: %v", err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("DecodeFrames() = %#v, want %#v", got, want)
	}
}

func TestDecodeFramesSupportsZeroLengthPayload(t *testing.T) {
	data := encodedFrame(0xa5, nil)
	got, err := DecodeFrames(data)
	if err != nil {
		t.Fatalf("DecodeFrames() returned unexpected error: %v", err)
	}
	if len(got) != 1 || got[0].Flags != 0xa5 || len(got[0].Payload) != 0 {
		t.Fatalf("DecodeFrames() = %#v, want one frame with flags 0xa5 and empty payload", got)
	}
}

func TestDecodeFramesSupportsMaximumPayloadLength(t *testing.T) {
	payload := make([]byte, 255)
	for i := range payload {
		payload[i] = byte(i)
	}
	data := encodedFrame(0xff, payload)

	got, err := DecodeFrames(data)
	if err != nil {
		t.Fatalf("DecodeFrames() returned unexpected error: %v", err)
	}
	if len(got) != 1 || got[0].Flags != 0xff || !bytes.Equal(got[0].Payload, payload) {
		t.Fatalf("maximum-length frame decoded incorrectly")
	}
}

func TestDecodeFramesEmptyInputReturnsNonNilEmptySlice(t *testing.T) {
	for _, data := range [][]byte{nil, {}} {
		got, err := DecodeFrames(data)
		if err != nil {
			t.Fatalf("DecodeFrames(empty) returned error: %v", err)
		}
		if got == nil {
			t.Fatal("DecodeFrames(empty) returned a nil slice")
		}
		if len(got) != 0 {
			t.Fatalf("DecodeFrames(empty) returned %#v", got)
		}
	}
}

func TestDecodeFramesRejectsTruncatedFrames(t *testing.T) {
	validPrefix := encodedFrame(0x01, []byte{0x02})
	tests := []struct {
		name string
		data []byte
	}{
		{name: "flags only", data: []byte{0x01}},
		{name: "missing zero-length checksum", data: []byte{0x01, 0x00}},
		{name: "payload truncated", data: []byte{0x01, 0x02, 0xaa}},
		{name: "checksum missing", data: []byte{0x01, 0x02, 0xaa, 0xbb}},
		{name: "truncated after valid frame", data: append(append([]byte(nil), validPrefix...), 0x44)},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := DecodeFrames(tc.data)
			if err == nil {
				t.Fatalf("DecodeFrames(%#v) returned nil error", tc.data)
			}
			if got != nil {
				t.Fatalf("DecodeFrames(%#v) returned partial result %#v, want nil", tc.data, got)
			}
		})
	}
}

func TestDecodeFramesRejectsBadChecksumWithoutPartialResult(t *testing.T) {
	first := encodedFrame(0x10, []byte{1, 2})
	bad := encodedFrame(0x20, []byte{3, 4})
	bad[len(bad)-1] ^= 0x01
	data := append(first, bad...)

	got, err := DecodeFrames(data)
	if err == nil {
		t.Fatal("DecodeFrames() accepted an incorrect checksum")
	}
	if got != nil {
		t.Fatalf("DecodeFrames() returned partial result %#v, want nil", got)
