func TestBroadcastDeliversInOrderIsolatesPayloadAndKeepsErrorsIndexed(t *testing.T) {
	payload := []byte{10, 20, 30}
	original := append([]byte(nil), payload...)
	firstErr := errors.New("first")
	thirdErr := errors.New("third")
	callOrder := make([]int, 0, 3)
	callCounts := [3]int{}

	handlers := []func([]byte) error{
		func(got []byte) error {
			callOrder = append(callOrder, 0)
			callCounts[0]++
			if !reflect.DeepEqual(got, original) {
				t.Errorf("first handler got %#v, want %#v", got, original)
			}
			got[0] = 99
			got = append(got, 40)
			return firstErr
		},
		func(got []byte) error {
			callOrder = append(callOrder, 1)
			callCounts[1]++
			if !reflect.DeepEqual(got, original) {
				t.Errorf("second handler got %#v, want original %#v", got, original)
			}
			got[1] = 88
			return nil
		},
		func(got []byte) error {
			callOrder = append(callOrder, 2)
			callCounts[2]++
			if !reflect.DeepEqual(got, original) {
				t.Errorf("third handler got %#v, want original %#v", got, original)
			}
			got[2] = 77
			return thirdErr
		},
	}

	gotErrors := Broadcast(payload, handlers)

	if !reflect.DeepEqual(callOrder, []int{0, 1, 2}) {
		t.Fatalf("call order was %#v, want [0 1 2]", callOrder)
	}
	if callCounts != [3]int{1, 1, 1} {
		t.Fatalf("call counts were %#v, want [1 1 1]", callCounts)
	}
	if len(gotErrors) != len(handlers) {
		t.Fatalf("got %d errors, want %d", len(gotErrors), len(handlers))
	}
	if gotErrors[0] != firstErr || gotErrors[1] != nil || gotErrors[2] != thirdErr {
		t.Fatalf("errors were %#v; want firstErr, nil, thirdErr", gotErrors)
	}
	if !reflect.DeepEqual(payload, original) {
		t.Fatalf("caller payload changed from %#v to %#v", original, payload)
	}
}

func TestBroadcastGivesEveryHandlerASeparateCopy(t *testing.T) {
	payload := []byte{1}
	var firstArg []byte

	handlers := []func([]byte) error{
		func(got []byte) error {
			firstArg = got
			return nil
		},
		func(got []byte) error {
			firstArg[0] = 42
			if got[0] != 1 {
				t.Errorf("second handler shared storage with first: got %d, want 1", got[0])
			}
			return nil
		},
	}

	gotErrors := Broadcast(payload, handlers)
	if len(gotErrors) != 2 || gotErrors[0] != nil || gotErrors[1] != nil {
		t.Fatalf("got errors %#v, want two nil entries", gotErrors)
	}
	if payload[0] != 1 {
		t.Fatalf("caller payload changed to %#v", payload)
	}
}

