func TestPollListenersDeliversInOrderAndIsolatesContext(t *testing.T) {
	context := map[string]string{"user": "forge", "region": "in"}
	original := map[string]string{"user": "forge", "region": "in"}
	callOrder := make([]int, 0, 3)
	callCounts := [3]int{}

	listeners := []func(string, map[string]string) bool{
		func(event string, got map[string]string) bool {
			callOrder = append(callOrder, 0)
			callCounts[0]++
			if event != "deploy" {
				t.Errorf("first listener event = %q, want deploy", event)
			}
			if !reflect.DeepEqual(got, original) {
				t.Errorf("first listener context = %#v, want %#v", got, original)
			}
			got["user"] = "changed"
			delete(got, "region")
			got["extra"] = "value"
			return false
		},
		func(event string, got map[string]string) bool {
			callOrder = append(callOrder, 1)
			callCounts[1]++
			if event != "deploy" {
				t.Errorf("second listener event = %q, want deploy", event)
			}
			if !reflect.DeepEqual(got, original) {
				t.Errorf("second listener saw modified context %#v, want %#v", got, original)
			}
			got["region"] = "us"
			return true
		},
		func(event string, got map[string]string) bool {
			callOrder = append(callOrder, 2)
			callCounts[2]++
			if event != "deploy" {
				t.Errorf("third listener event = %q, want deploy", event)
			}
			if !reflect.DeepEqual(got, original) {
				t.Errorf("third listener saw modified context %#v, want %#v", got, original)
			}
			return false
		},
	}

	got := PollListeners("deploy", context, listeners)

	if !reflect.DeepEqual(got, []bool{false, true, false}) {
		t.Fatalf("results = %#v, want [false true false]", got)
	}
	if !reflect.DeepEqual(callOrder, []int{0, 1, 2}) {
		t.Fatalf("call order = %#v, want [0 1 2]", callOrder)
	}
	if callCounts != [3]int{1, 1, 1} {
		t.Fatalf("call counts = %#v, want [1 1 1]", callCounts)
	}
	if !reflect.DeepEqual(context, original) {
		t.Fatalf("caller context changed from %#v to %#v", original, context)
	}
}

func TestPollListenersProvidesIndependentWritableMaps(t *testing.T) {
	var firstMap map[string]string
	listeners := []func(string, map[string]string) bool{
		func(_ string, got map[string]string) bool {
			firstMap = got
			got["created"] = "first"
			return true
		},
		func(_ string, got map[string]string) bool {
			if _, exists := got["created"]; exists {
				t.Error("second listener received the first listener's map state")
			}
			got["created"] = "second"
			if firstMap["created"] != "first" {
				t.Error("second listener shared map storage with first listener")
			}
			return true
		},
	}

	got := PollListeners("empty", nil, listeners)
	if !reflect.DeepEqual(got, []bool{true, true}) {
		t.Fatalf("results = %#v, want [true true]", got)
	}
}

